mapper.select:
SELECT media_asset_id
 FROM media_asset_checksums
 WHERE account_id = #{accountId}
   AND sha256 = #{sha256}
 FOR UPDATE

SELECT 
  FROM media_assets
 WHERE 

   AND asset_type = #{type}


   AND status = #{status}


   AND (LOWER(original_filename) LIKE LOWER(CONCAT('%', #{search}, '%'))
        OR LOWER(storage_key) LIKE LOWER(CONCAT('%', #{search}, '%')))


   AND (created_at < #{cursorCreatedAt}
        OR (created_at = #{cursorCreatedAt} AND id < #{cursorId,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}))

 ORDER BY created_at DESC, id DESC
 LIMIT #{limit}

mapper.delete:
DELETE FROM media_asset_checksums
 WHERE account_id = #{accountId}
   AND media_asset_id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}

mapper.update:
UPDATE media_assets
   SET status = 'UPLOADING'
 WHERE account_id = #{accountId}
   AND id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND status = 'PENDING_UPLOAD'
   AND deleted_at IS NULL

UPDATE media_assets
   SET status = 'VALIDATING'
 WHERE account_id = #{accountId}
   AND id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND status = 'UPLOADING'
   AND deleted_at IS NULL

UPDATE media_assets
   SET status = 'REJECTED'
 WHERE account_id = #{accountId}
   AND id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND status = 'VALIDATING'
   AND deleted_at IS NULL
